typedef struct { atomic_bool cancelled; } cancel_token;

static bool check_cancelled(const cancel_token *t) {
    return atomic_load_explicit(&t->cancelled, memory_order_relaxed);
}

while (!check_cancelled(token)) {           /* safe point */
    if (cnd_timedwait(&work_ready, &m, ts) == thrd_success)
        process_chunk();                     /* also re-check after the wait */
}

/* thread side: cancellation is delivered at deferred points */
pthread_setcancelstate(PTHREAD_CANCEL_ENABLE, NULL);   /* default type: deferred */
for (;;) {
    pthread_testcancel();                 /* explicit cancellation point */
    chunk = read(fd, buf, sizeof buf);    /* read is also a cancellation point */
    if (chunk <= 0) break;
    process(buf, chunk);
}
/* requester side */
pthread_cancel(worker);                   /* request, delivered at the next point */

